#include <stdio.h>

struct Client {
    int accountID;
    char accountname[50];
    char address[50];
    float balance;
};

int main() {
    struct Client c[10];
    int i;

    for (i = 0; i < 10; i++) {
        printf("Enter Account ID, Name, Address and Balance for client %d:\n", i + 1);
        scanf("%d %s %s %f", &c[i].accountID, c[i].accountname, c[i].address, &c[i].balance);
    }

    printf("\n--- Client Details ---\n");
    for (i = 0; i < 10; i++) {
        printf("ID: %d | Name: %s | Address: %s | Balance: %.2f\n", c[i].accountID, c[i].accountname, c[i].address, c[i].balance);
    }

    return 0;
}

#include <stdio.h>

int main() {
    FILE *fptr;
    fptr = fopen("student.txt", "w");

    if (fptr == NULL) {
        printf("Error opening file!");
        return 1;
    }

    fprintf(fptr, "Welcome to C File Handling.\n");
    fclose(fptr);
    printf("Data written successfully.");

    return 0;
}
